// FASE 1: Almacenar acciones individuales
const actionData = $json;

if (!actionData.type || !actionData.sessionId) {
  return [{ json: { success: false, error: 'Invalid action data' } }];
}

const enrichedAction = {
  ...actionData,
  capturedAt: new Date().toISOString(),
  actionId: `action_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
};

const sessionId = actionData.sessionId;
const sessionKey = `session_${sessionId}`;

// Simulamos almacenamiento en memoria (en producción usar base de datos)
if (!global.sessionActions) {
  global.sessionActions = {};
}

if (!global.sessionActions[sessionKey]) {
  global.sessionActions[sessionKey] = [];
}

global.sessionActions[sessionKey].push(enrichedAction);

console.log(`Action stored for session ${sessionId}. Total: ${global.sessionActions[sessionKey].length}`);

return [{
  json: {
    success: true,
    message: 'Action captured and stored',
    sessionId: sessionId,
    actionId: enrichedAction.actionId,
    totalActions: global.sessionActions[sessionKey].length,
    timestamp: enrichedAction.capturedAt
  }
}];

// FASE 2: Recuperar acciones y procesar
const request = $json;
const sessionId = request.sessionId;

if (!sessionId) {
  return [{ json: { success: false, error: 'Session ID required' } }];
}

const sessionKey = `session_${sessionId}`;
const sessionActions = global.sessionActions?.[sessionKey] || [];

if (sessionActions.length === 0) {
  return [{ json: { success: false, error: 'No actions found for session' } }];
}

if (sessionActions.length < 3) {
  return [{ json: { success: false, error: 'At least 3 actions required' } }];
}

const processedData = {
  sessionId: sessionId,
  totalActions: sessionActions.length,
  captureStartTime: sessionActions[0]?.capturedAt,
  captureEndTime: sessionActions[sessionActions.length - 1]?.capturedAt,
  sourceUrl: request.url || sessionActions[0]?.url || '',
  pageTitle: request.title || sessionActions[0]?.title || 'Test Session',
  userAgent: request.userAgent || 'TestBuilder Extension',
  actions: sessionActions.map((action, index) => ({
    ...action,
    actionIndex: index + 1,
    relativeTime: action.timestamp ? action.timestamp - sessionActions[0].timestamp : 0
  }))
};

return [{ json: processedData }];

