// Procesar respuesta y limpiar sesión
const response = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const originalData = $('Retrieve Actions').item.json;

// Limpiar sesión
const sessionKey = `session_${originalData.sessionId}`;
if (global.sessionActions?.[sessionKey]) {
  delete global.sessionActions[sessionKey];
}

const cleanCode = response.replace(/```typescript/gi, '').replace(/```/g, '').trim();

return [{
  json: {
    success: true,
    sessionId: originalData.sessionId,
    message: 'Tests generated from captured actions',
    timestamp: new Date().toISOString(),
    tests: {
      playwright: {
        code: cleanCode,
        filename: `test-${Date.now()}.spec.ts`
      }
    },
    summary: {
      actionsProcessed: originalData.totalActions,
      captureTime: originalData.captureStartTime + ' - ' + originalData.captureEndTime
    }
  }
}];
